motif = {(25,8):2,(26,6):0,(26,7):2,(27,6):2,(27,7):0}
for (r,c),v in motif.items(): g[r][c]=v
def line_cells(cells):
    cells = sorted(cells)
    (r0,c0),(r1,c1) = cells[0], cells[-1]
    dr = (r1-r0)//max(1,abs(r1-r0)) if r1!=r0 else 0
    dc = (c1-c0)//max(1,abs(c1-c0)) if c1!=c0 else 0
    full = []
    r,c = r0,c0
    while 0<=r<28 and 0<=c<12:
        full.append((r,c)); r+=dr; c+=dc
    return set(full)
from collections import defaultdict
bycolor = defaultdict(list)
for (r,c),v in motif.items(): bycolor[v].append((r,c))
for v,cells in bycolor.items():
    if len(cells) >= 2:
        s = line_cells(cells)
        for (r,c) in s:
            if g[r][c]==5: g[r][c]=v
for row in g: print(row)

g = [[5]*12 for _ in range(28)]
for (r,c),v in motif.items(): g[r][c]=v
for v,cells in bycolor.items():
    if len(cells) >= 2:
        cells = sorted(cells)
        (r0,c0),(r1,c1) = cells[0], cells[-1]
        n = max(abs(r1-r0), abs(c1-c0))
        dr,dc = (r1-r0)//n, (c1-c0)//n
        for (r,c) in cells:
            rr,cc = r-dr, c-dc
            while 0<=rr<28 and 0<=cc<12:
                if g[rr][cc]==5: g[rr][cc]=v
                rr-=dr; cc-=dc
            rr,cc = r+dr, c+dc
            while 0<=rr<28 and 0<=cc<12:
                if g[rr][cc]==5: g[rr][cc]=v
                rr+=dr; cc+=dc
out = [row[:] for row in g]
# mark changed cells
for r in range(28):
    for c in range(12):
        if (r,c) in motif and g[r][c]==motif[(r,c)]: continue
for row in out: print(''.join(str(x) for x in row))
